-- Step BC-3: the flag-and-fan template's door is RIGHT hand.
-- Run by Nathan in the Supabase SQL editor. Safe to re-run.
-- Run any time after sql/step-bc2, which is already live.
--
-- The reviewer compared the live template with Integrate's own drawing 15 and
-- found the one thing sql/step-bc2 got wrong: in
--
--     "Single Door With Flag And Fan Lights"   (Integrate template 69)
--
-- the door leaf is LEFT hand hung, and Integrate's is RIGHT (operation 18).
-- The board's default for a single door is left hand, which is correct for
-- templates 70, 71 and 72 — Integrate has those left hand too — and wrong for
-- this one alone.
--
-- WHAT CHANGES: one template's tree, and in it one value —
-- `doorLeafPart.operation` from 'left_hand_hung' to 'right_hand_hung'. The
-- tree below was GENERATED by the board's own code from the template spec
-- that now lives in `src/drawingBoard/doorOpenings.js`
-- (FLAG_FRAME_TEMPLATES), so the template, the tests and this file read one
-- definition. Everything else about the template — the three frames, the
-- transoms, the fanlights at 62, the flags' fixed lights at 86 — is
-- unchanged, and SECTION 0 lets that be checked rather than trusted.
--
-- NO DRAWING IS TOUCHED. A drawing already made from this template keeps its
-- own tree and its own hand, which is a surveyor's choice once the drawing
-- exists. The hand only matters here for what a NEW drawing starts with.
--
-- The hand drives the ironmongery: `is_left_hand_hung_viewed_internally` and
-- `is_right_hand_hung_viewed_internally` are what the mpls allocator rules
-- band on, so a template handed the wrong way round starts every new drawing
-- with the wrong strike and keep.
--
-- RUN SECTION 0 FIRST.

-- ═══════════════════════════════════════════════════════════════════════════
-- SECTION 0 — read before changing
-- ═══════════════════════════════════════════════════════════════════════════

-- 0a. The template as it stands. Expect ONE row, sort_order 130.
SELECT id, name, family, group_name, window_type, sort_order, is_active, updated_at
FROM   public.drawing_templates
WHERE  name = 'Single Door With Flag And Fan Lights';

-- 0b. Its door leaf's hand, which is the value this file changes. Expect
--     ["left_hand_hung"] before, ["right_hand_hung"] after.
SELECT (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, '$.**.values ? (@.mechanicalClearanceTop == 2).operation') v) AS leaf_operation
FROM   public.drawing_templates
WHERE  name = 'Single Door With Flag And Fan Lights';

-- 0c. Everything else about it, so the replacement can be compared with it:
--     three frames, one container, one leaf, five casement sashes, three
--     transoms, three cills.
SELECT (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "assemblyFramePart")')) AS frames,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "containerPart")'))     AS containers,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "doorLeafPart")'))      AS leaves,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "casementSashPart")'))  AS sashes,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "transomPart")'))       AS transoms,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "cillPart")'))          AS cills,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(tree, '$.**.values ? (@.mechanicalClearanceTop == 1).bottomHeight') v) AS sash_rails
FROM   public.drawing_templates
WHERE  name = 'Single Door With Flag And Fan Lights';

-- 0d. The other three flag templates, which this file does NOT touch. Their
--     leaves are left hand and stay that way.
SELECT name, sort_order,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, '$.**.values ? (@.mechanicalClearanceTop == 2).operation') v) AS leaf_operation
FROM   public.drawing_templates
WHERE  name IN (
    'Single Door With Flag Lights',
    'Single Door With Flag Light Right',
    'Single Door With Flag Light Left'
)
ORDER  BY sort_order;


-- ═══════════════════════════════════════════════════════════════════════════
-- SECTION 1 — the right-hand tree
-- ═══════════════════════════════════════════════════════════════════════════

BEGIN;

DO $$
DECLARE
  _profile_id  bigint;
  _single_code text;
  _templates   jsonb := '[{"name":"Single Door With Flag And Fan Lights","sort_order":130,"tree":{"key":"item_jq64prz","part_type":"drawingItemPart","values":{"typeOfWork":"complete_new","frameMaterialId":"utile","sashMaterialId":"utile","cillMaterialId":"utile","quantity":1},"children":[{"key":"paint_7comzlc","part_type":"paintAndIronmongeryPart","values":{"internalFinish":"clean_white","externalFinish":"clean_white","cillFinish":"clean_white","cutOutBrickReveal":false,"ironmongeryFinish":"PB","isDoorMpls":true},"children":[]},{"key":"notes_lmltc4j","part_type":"notesPart","values":{},"children":[]},{"key":"price_iv0vzex","part_type":"pricePart","values":{},"children":[]},{"key":"frames_ywk4ero","part_type":"containerPart","values":{"bayTypeId":176,"partSpacing":-47,"isCoupledInTheFactory":false,"isBayPoleRequired":false,"hasContinousSubCill":false,"isCornerpostRequired":false},"children":[{"key":"flagframe_3a3q23o","part_type":"assemblyFramePart","values":{"width":650,"height":1632,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"flagframe_3a3q23o_trans","part_type":"transomPart","values":{"offset":348,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"flagframe_3a3q23o_fan","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_3a3q23o_fan_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_3a3q23o_light","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_3a3q23o_light_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_3a3q23o_cill","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]},{"key":"frame_c82ewyk","part_type":"assemblyFramePart","values":{"width":1082,"height":2496,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"trans_vq6vogx","part_type":"transomPart","values":{"offset":348,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"cas_x1wzae0","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"cas_x1wzae0_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"doorleaf_t4x8afp","part_type":"doorLeafPart","values":{"operation":"right_hand_hung","casementTypeId":"open_out","thickness":54,"topHeight":110,"leftWidth":110,"rightWidth":110,"bottomHeight":163,"bottomHeightExternal":170,"btmRailShapeId":"stepped","mechanicalClearanceTop":2,"mechanicalClearanceLeft":3,"mechanicalClearanceRight":3,"mechanicalClearanceBottom":3,"archHead":false,"toBeReplaced":true},"children":[{"key":"doorleaf_t4x8afp_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"cill_ngfjtls","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]},{"key":"flagframe_mlfkouh","part_type":"assemblyFramePart","values":{"width":650,"height":1632,"leftWidth":47,"rightWidth":47,"topHeight":47,"bottomHeight":37,"frameDepth":96,"jambType":"solid_profiled","frameHeadStopSize":20,"frameStileStopSize":20,"cillStopSize":26,"rakeFrame":false,"archHead":false,"toBeReplaced":true},"children":[{"key":"flagframe_mlfkouh_trans","part_type":"transomPart","values":{"offset":348,"thicknessInFrame":41,"transomStopSize":18,"startDivider":"0","endDivider":"0"},"children":[]},{"key":"flagframe_mlfkouh_fan","part_type":"casementSashPart","values":{"operation":"top_hung","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":62,"bottomHeightExternal":69,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_mlfkouh_fan_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_mlfkouh_light","part_type":"casementSashPart","values":{"operation":"fix","casementTypeId":"open_out","thickness":54,"topHeight":62,"leftWidth":62,"rightWidth":62,"bottomHeight":86,"bottomHeightExternal":93,"btmRailShapeId":"stepped","mechanicalClearanceTop":1,"mechanicalClearanceLeft":1,"mechanicalClearanceRight":1,"mechanicalClearanceBottom":2,"toBeReplaced":true},"children":[{"key":"flagframe_mlfkouh_light_glass","part_type":"glassPart","values":{"glazingId":"double_glazing","isIndividualPanes":false,"internalGlassPartNo":"GL100010","externalGlassPartNo":"GL100080","glazingRebateWidth":15,"glazingTolerance":3},"children":[]}]},{"key":"flagframe_mlfkouh_cill","part_type":"cillPart","values":{"height":37,"depth":145},"children":[]}]}]}]}}]'::jsonb;
  _row         record;
  _tree        jsonb;
  _rows        int;
BEGIN
  SELECT id INTO _profile_id FROM public.default_profiles
  WHERE code = 'open_out_doors' AND is_active = TRUE;
  IF _profile_id IS NULL THEN
    RAISE EXCEPTION 'No active default_profiles row with code ''open_out_doors''';
  END IF;

  SELECT code INTO _single_code FROM public.reference_options
  WHERE category = 'product' AND lower(label) = 'door' AND is_active
  ORDER BY sort_order LIMIT 1;
  IF _single_code IS NULL THEN
    RAISE EXCEPTION 'No active reference_options row with category ''product'' and label ''Door''';
  END IF;

  -- This file CORRECTS a template; it does not create one. If the row is not
  -- there, sql/step-bc2 has not been run and this is the wrong file to fix it.
  IF NOT EXISTS (
    SELECT 1 FROM public.drawing_templates
    WHERE name = 'Single Door With Flag And Fan Lights'
  ) THEN
    RAISE EXCEPTION 'Template "Single Door With Flag And Fan Lights" does not exist — run sql/step-bc2-flag-frame-templates.sql first';
  END IF;

  IF jsonb_array_length(_templates) <> 1 THEN
    RAISE EXCEPTION 'Expected 1 template in this script, found %', jsonb_array_length(_templates);
  END IF;

  FOR _row IN
    SELECT * FROM jsonb_to_recordset(_templates) AS x(name text, sort_order int, tree jsonb)
  LOOP
    _tree := jsonb_set(_row.tree, '{values,product}', to_jsonb(_single_code), true);

    -- The tree being written must BE right hand, or this file has achieved
    -- nothing and would say it had.
    IF NOT jsonb_path_exists(_tree, '$.**.values ? (@.operation == "right_hand_hung" && @.mechanicalClearanceTop == 2)') THEN
      RAISE EXCEPTION 'The replacement tree has no right-hand door leaf — do not run this file';
    END IF;

    UPDATE public.drawing_templates
    SET tree = _tree, default_profile_id = _profile_id, window_type = 'Door',
        sort_order = _row.sort_order, updated_at = now()
    WHERE name = _row.name;

    GET DIAGNOSTICS _rows = ROW_COUNT;
    IF _rows <> 1 THEN
      RAISE EXCEPTION 'Expected to update exactly 1 template, updated %', _rows;
    END IF;
    RAISE NOTICE 'Step BC-3: % is right hand hung', _row.name;
  END LOOP;
END $$;

COMMIT;

-- ── Checks ─────────────────────────────────────────────────────────────────

-- 1. The hand, after. Expect ["right_hand_hung"].
SELECT name, sort_order,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, '$.**.values ? (@.mechanicalClearanceTop == 2).operation') v) AS leaf_operation
FROM   public.drawing_templates
WHERE  name = 'Single Door With Flag And Fan Lights';

-- 2. Everything else, to compare with SECTION 0c: three frames, one
--    container, one leaf, five sashes, three transoms, three cills, and the
--    rails still 62 on the three fanlights and 86 on the two flag lights.
SELECT (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "assemblyFramePart")')) AS frames,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "containerPart")'))     AS containers,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "doorLeafPart")'))      AS leaves,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "casementSashPart")'))  AS sashes,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "transomPart")'))       AS transoms,
       (SELECT count(*) FROM jsonb_path_query(tree, '$.**.part_type ? (@ == "cillPart")'))          AS cills,
       (SELECT jsonb_agg(v ORDER BY v::text) FROM jsonb_path_query(tree, '$.**.values ? (@.mechanicalClearanceTop == 1).bottomHeight') v) AS sash_rails,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, '$.**.values.partSpacing') v)               AS part_spacing
FROM   public.drawing_templates
WHERE  name = 'Single Door With Flag And Fan Lights';

-- 3. The other three are untouched and still left hand.
SELECT name, sort_order, updated_at,
       (SELECT jsonb_agg(v) FROM jsonb_path_query(tree, '$.**.values ? (@.mechanicalClearanceTop == 2).operation') v) AS leaf_operation
FROM   public.drawing_templates
WHERE  name IN (
    'Single Door With Flag Lights',
    'Single Door With Flag Light Right',
    'Single Door With Flag Light Left'
)
ORDER  BY sort_order;


-- ---------------------------------------------------------------------------
-- DO NOT RUN — rollback, only if this step has to be undone
-- ---------------------------------------------------------------------------
